#nullable enable // autogenerated

using MVZ2.GameContent.Contraptions;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Grids;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Grids;
using PVZEngine.Level;
using UnityEngine;

namespace MVZ2.GameContent.Buffs.Grids
{
    [AutoBuffDefinition(VanillaBuffNames.Grid.timeBombExplosion)]
    public class TimeBombExplosionBuff : BuffDefinition
    {
        public TimeBombExplosionBuff(string nsp, string name) : base(nsp, name)
        {
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            var tile = buff.Target as LawnGrid;
            if (tile != null)
            {
                var offset = GetOffset(buff);
                var position = tile.GetEntityPosition() + offset;
                var range = GetRange(buff);
                var damage = GetDamage(buff);
                var faction = GetFaction(buff);
                var source = GetSource(buff);
                TimeBomb.ExplodeSingle(buff.Level, position, range, damage, faction, source);

                var spread = (TileDirection)GetSpread(buff);
                foreach (var direction in LogicGridExt.allTileDirections)
                {
                    if (!spread.HasFlag(direction))
                        continue;
                    var newTile = tile.GetDirectionedTile(direction);
                    if (newTile == null)
                        continue;
                    var newBuff = newTile.NewBuff<TimeBombExplosionBuff>();
                    TimeBombExplosionBuff.SetOffset(newBuff, offset);
                    TimeBombExplosionBuff.SetDamage(newBuff, damage);
                    TimeBombExplosionBuff.SetRange(newBuff, range);
                    TimeBombExplosionBuff.SetFaction(newBuff, faction);
                    TimeBombExplosionBuff.SetSource(newBuff, source);
                    TimeBombExplosionBuff.SetSpread(newBuff, (int)direction);
                    newTile.AddBuff(newBuff);
                }
            }
            buff.Remove();
        }
        public static Vector3 GetOffset(Buff buff) => buff.GetProperty<Vector3>(PROP_OFFSET);
        public static void SetOffset(Buff buff, Vector3 value) => buff.SetProperty(PROP_OFFSET, value);
        public static float GetRange(Buff buff) => buff.GetProperty<float>(PROP_RANGE);
        public static void SetRange(Buff buff, float value) => buff.SetProperty(PROP_RANGE, value);
        public static float GetDamage(Buff buff) => buff.GetProperty<float>(PROP_DAMAGE);
        public static void SetDamage(Buff buff, float value) => buff.SetProperty(PROP_DAMAGE, value);
        public static int GetFaction(Buff buff) => buff.GetProperty<int>(PROP_FACTION);
        public static void SetFaction(Buff buff, int value) => buff.SetProperty(PROP_FACTION, value);
        public static ILevelSourceReference? GetSource(Buff buff) => buff.GetProperty<ILevelSourceReference>(PROP_SOURCE);
        public static void SetSource(Buff buff, ILevelSourceReference? value) => buff.SetProperty(PROP_SOURCE, value);
        public static int GetSpread(Buff buff) => buff.GetProperty<int>(PROP_SPREAD);
        public static void SetSpread(Buff buff, int value) => buff.SetProperty(PROP_SPREAD, value);
        public static readonly VanillaBuffPropertyMeta<Vector3> PROP_OFFSET = new VanillaBuffPropertyMeta<Vector3>("offset");
        public static readonly VanillaBuffPropertyMeta<float> PROP_RANGE = new VanillaBuffPropertyMeta<float>("range");
        public static readonly VanillaBuffPropertyMeta<float> PROP_DAMAGE = new VanillaBuffPropertyMeta<float>("damage");
        public static readonly VanillaBuffPropertyMeta<int> PROP_FACTION = new VanillaBuffPropertyMeta<int>("faction");
        public static readonly VanillaBuffPropertyMeta<ILevelSourceReference> PROP_SOURCE = new VanillaBuffPropertyMeta<ILevelSourceReference>("source");
        public static readonly VanillaBuffPropertyMeta<int> PROP_SPREAD = new VanillaBuffPropertyMeta<int>("spread");
    }
}
